<section class="card"><form class="filters inline-filters" method="get" action="index.php"><input type="hidden" name="r" value="perusahaan"><label>Nama / Alamat Perusahaan<input name="keyword" value="<?= e(query('keyword')) ?>" placeholder="Cari perusahaan…"></label><label>Status Verifikasi<select name="status"><option value="">Semua status</option><?php foreach(['Menunggu','Terverifikasi','Ditolak'] as $s):?><option<?= selected(query('status'),$s) ?>><?= e($s) ?></option><?php endforeach;?></select></label><button class="button">Cari Perusahaan</button><a class="button text" href="<?= e(url('perusahaan')) ?>">Reset</a></form></section>
<div class="job-grid"><?php foreach($perusahaan as $p):?><article class="card company-card"><div class="section-heading"><span class="company-avatar"><?= e(initials($p['namaPerusahaan'])) ?></span><?= badge($p['statusVerifikasi']) ?></div><h2><?= e($p['namaPerusahaan']) ?></h2><p class="muted"><?= e($p['bidangUsaha']) ?></p><p class="job-meta"><?= icon('location') ?> <?= e($p['alamat']) ?></p><p><?= e($p['emailPerusahaan']) ?></p><div class="card-bottom"><a class="button secondary full" href="<?= e(url('perusahaan/detail',['id'=>$p['idPerusahaan']])) ?>">Tinjau Perusahaan <?= icon('arrow') ?></a></div></article><?php endforeach;?></div><?php if(!$perusahaan):?><div class="card empty-state"><?= icon('building') ?><h2>Perusahaan tidak ditemukan</h2><p>Coba ubah pencarian atau filter status.</p></div><?php endif;?>
